    // schedule for the Jacobi sweeps.
    Target target = get_host_target();
    const int vec_width = target.natural_vector_size(type_of<num_t>());
    const int tile_size = vec_width * 32;  // number of points per parallel chunk

    Var ko("ko"), ki("ki");

    // Schedule: compute at root, split the 1D domain into tiles, parallelize
    // across tiles, and vectorize within each tile. This improves both
    // computational throughput and memory bandwidth usage.
    jacobi_A_to_B
        .compute_root()
        .split(k, ko, ki, tile_size)
        .vectorize(ki, vec_width)
        .parallel(ko);

